using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace EasyJava2 {
public static class Program {
 public static Icon Icon;
 [DllImport("user32.dll")]static extern bool SetProcessDPIAware();
 [STAThread]public static int Main(string[] args){try{if(Environment.OSVersion.Version.Major>=6)SetProcessDPIAware();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Icon=System.Drawing.Icon.ExtractAssociatedIcon(Application.ExecutablePath);
  if(args.Length>1&&args[0]=="--snapshot-parrot"){int result=0;using(CancellationTokenSource cancel=new CancellationTokenSource())using(CommandWindow popup=new CommandWindow("cmd","curl parrot.live","",30,delegate{cancel.Cancel();})){popup.Shown+=async delegate{Task<CommandResult> command=null;try{command=CommandRunner.Run("cmd","curl parrot.live","",30,cancel.Token,delegate(bool error,string chunk){if(error)popup.AppendError(chunk);else popup.AppendOutput(chunk);});DateTime until=DateTime.UtcNow.AddSeconds(12);while(DateTime.UtcNow<until&&(popup.Terminal.PlainText.Trim().Length<100||popup.Terminal.PlainText.Split('\n').Length<18)&&!command.IsCompleted)await Task.Delay(50);if(popup.Terminal.PlainText.Trim().Length<100||popup.Terminal.PlainText.Split('\n').Length<18)throw new Exception("Nie odebrano animacji parrot.live: "+popup.ErrorText.Text);Application.DoEvents();using(Bitmap bitmap=new Bitmap(popup.Width,popup.Height)){popup.DrawToBitmap(bitmap,new Rectangle(0,0,popup.Width,popup.Height));bitmap.Save(args[1]);}}catch(Exception ex){File.WriteAllText(args[1]+".error",ex.ToString());result=1;}cancel.Cancel();if(command!=null)try{await command;}catch(OperationCanceledException){}catch(Exception ex){File.WriteAllText(args[1]+".error",ex.ToString());result=1;}popup.Cancelled();if(args.Length<3||args[2]!="--keep-open")popup.Close();};Application.Run(popup);}return result;}
  if(args.Length>1&&args[0]=="--snapshot-command"){int result=0;using(CommandWindow popup=new CommandWindow("powershell","Write-Output 'Witaj z PowerShell'",Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),30,delegate{})){popup.Shown+=async delegate{try{CommandResult done=await CommandRunner.Run("powershell","Write-Output 'Witaj z PowerShell'", "",30,CancellationToken.None,delegate(bool error,string chunk){if(error)popup.AppendError(chunk);else popup.AppendOutput(chunk);});popup.Complete(done);Application.DoEvents();using(Bitmap bitmap=new Bitmap(popup.Width,popup.Height)){popup.DrawToBitmap(bitmap,new Rectangle(0,0,popup.Width,popup.Height));bitmap.Save(args[1]);}}catch(Exception ex){File.WriteAllText(args[1]+".error",ex.ToString());result=1;}if(args.Length<3||args[2]!="--keep-open")popup.Close();};Application.Run(popup);}return result;}
  if(args.Length>1&&args[0]=="--snapshot-timing"){using(TimingDialog f=new TimingDialog(.5,delegate(double seconds){})){f.Show();Application.DoEvents();using(Bitmap bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(args[1]);}f.Close();}return 0;}
  if(args.Length>1&&args[0]=="--selftest")return Tests.Run(args[1]); if(args.Length>1&&args[0]=="--allfeatures")return AllFeatureTests.Suite(args[1]);
  if(args.Length>1&&args[0]=="--examples"){Directory.CreateDirectory(args[1]);for(int i=1;i<=8;i++){Project p=Examples.Create(i);ProjectIO.Write(Path.Combine(args[1],ProjectIO.Safe(p.Name)+".js"),p,Application.ExecutablePath);}return 0;}
  if(args.Length>1&&(args[0]=="--player"||args[0]=="--smoke"))return Player(ProjectIO.Read(args[1]),args[0]=="--smoke");
  if(args.Length>1&&(args[0]=="--snapshot"||args[0]=="--snapshot-gui"||args[0]=="--snapshot-terminal")){int result=0;using(Editor editor=new Editor("")){if(args[0]=="--snapshot-gui")editor.Project=Examples.Gui();if(args[0]=="--snapshot-terminal")editor.Project=Examples.Terminal();editor.Shown+=async delegate{try{await editor.Snapshot(args[1],args[0]=="--snapshot-terminal");}catch(Exception e){File.WriteAllText(args[1]+".error",e.ToString());result=1;}editor.Close();};Application.Run(editor);}return result;}
  using(Editor editor=new Editor(args.Length>0?args[0]:null))Application.Run(editor);return 0;
 }catch(Exception e){if(args.Length>0&&args[0]=="--player"){MessageBox.Show(e.Message,"EasyJava",MessageBoxButtons.OK,MessageBoxIcon.Error);}else if(args.Any(x=>x.StartsWith("--"))){try{File.WriteAllText(Path.Combine(Path.GetTempPath(),"easyjava-error.txt"),e.ToString());}catch{}}else MessageBox.Show(e.Message,"EasyJava",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 static int Player(Project p,bool smoke){int result=0;using(Form form=new Form{Text=p.Name,Icon=Icon,ClientSize=new Size(800,620),StartPosition=FormStartPosition.CenterScreen,MinimumSize=new Size(320,250),KeyPreview=true,ShowInTaskbar=!smoke,WindowState=smoke?FormWindowState.Minimized:FormWindowState.Normal})using(RuntimeView view=new RuntimeView(true)){form.Controls.Add(view);view.Silent=smoke;view.WindowChanged=(title,size)=>{form.Text=title;Rectangle area=Screen.FromControl(form).WorkingArea;form.ClientSize=new Size(Math.Min(size.Width,area.Width-40),Math.Min(size.Height+43,area.Height-75));};form.Shown+=async delegate{System.Windows.Forms.Timer timeout=null;if(smoke){timeout=new System.Windows.Forms.Timer{Interval=1200};timeout.Tick+=delegate{timeout.Stop();view.Stop();};timeout.Start();}await view.Start(p);if(smoke){await Task.Delay(150);view.Stop();result=view.Errors.Count==0?0:1;if(timeout!=null)timeout.Dispose();form.Close();}};form.FormClosing+=delegate{view.Stop();};Application.Run(form);}return result;}
}

public static class Tests {
 static void Assert(bool v,string text){if(!v)throw new Exception(text);}
 static Block B(string k,params string[] a){return Block.Make(k,a);}
 public static int Run(string directory){Directory.CreateDirectory(directory);int exit=0;List<string> results=new List<string>();using(Form form=new Form{ShowInTaskbar=false,WindowState=FormWindowState.Minimized})using(RuntimeView runtime=new RuntimeView()){form.Controls.Add(runtime);runtime.Silent=true;runtime.ShowCommandWindows=false;form.Shown+=async delegate{try{
  DragDropTests.Run(results);
  TerminalTests.Run(results);
  PauseUiTests.Run(results);
  await TimingTests.Run(runtime,results);
  await CommandTests.Run(runtime,results,directory);
  await CommandWindowTests.Run(results);
  await AllFeatureTests.Run(runtime,results,directory);
  await StandaloneTests.Run(results,directory);
  using(Editor timingEditor=new Editor("")){
   timingEditor.SetStepDelay(.5);Assert(timingEditor.Project.StepDelaySeconds==.5,"Ustawienie odstępu w edytorze");
   typeof(Editor).GetMethod("Undo",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(timingEditor,null);Assert(timingEditor.Project.StepDelaySeconds==0,"Cofanie odstępu");
   typeof(Editor).GetMethod("Redo",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(timingEditor,null);Assert(timingEditor.Project.StepDelaySeconds==.5,"Ponawianie odstępu");
  }
  results.Add("PASS odstępy: ustawienie w edytorze oraz cofanie i ponawianie zmiany");

  Assert(Catalog.All.Count>=90,"Za mało bloczków");results.Add("PASS katalog: "+Catalog.All.Count+" bloczków / "+Catalog.Groups.Length+" kategorii");
  Project p=Examples.Gui();string json=ProjectIO.Json(p);Assert(ProjectIO.Json(ProjectIO.FromJson(json))==json,"Zapis/odczyt JSON");string js=ProjectIO.Export(p,Application.ExecutablePath);Assert(ProjectIO.Json(ProjectIO.Parse(js))==json,"Plik JS musi zachować bloczki");Assert(js.StartsWith("//"),"JS nie może zaczynać się od JSON");results.Add("PASS jeden plik .js: wykonywalny kod + ponowna edycja bloczków");
  Project old=ProjectIO.FromJson("{\"Version\":1,\"Name\":\"stary\",\"Blocks\":[{\"Kind\":\"say\",\"A\":\"Czesc\",\"Children\":[]}]}");Assert(old.Blocks[0].Else!=null&&old.Version==2,"Migracja v1");results.Add("PASS import wcześniejszych bloczków, także JSON z rozszerzeniem .js");
  await runtime.Start(p);Assert(runtime.Errors.Count==0&&runtime.Stage.Elements.Count==9,"GUI: "+string.Join(";",runtime.Errors));((TextBox)runtime.Stage.Elements["imie"].Control).Text="Karol";((Button)runtime.Stage.Elements["hello"].Control).PerformClick();await Task.Delay(70);Assert(runtime.Stage.Elements["wynik"].Control.Text.Contains("Karol")&&RuntimeView.Number(runtime.Get("punkty"))==1,"Zdarzenie przycisku");((TrackBar)runtime.Stage.Elements["slider"].Control).Value=73;await Task.Delay(30);Assert(((ProgressBar)runtime.Stage.Elements["progress"].Control).Value==73,"Zdarzenie suwaka");results.Add("PASS prawdziwe GUI: przyciski, pola, suwak, pasek postępu, zdarzenia");
  p=new Project();p.Blocks.AddRange(new[]{B("set","n","2,5"),B("change","n","1,5"),B("math","wynik","{n}","*","3"),B("set","expr","=sqrt(25) + n * 2"),B("list_create","lista","A|B"),B("list_add","lista","C"),B("list_get","lista","2","element"),B("list_length","lista","ile")});Block condition=B("if_else","{n}","4");condition.Children.Add(B("set","branch","tak"));condition.Else.Add(B("set","branch","nie"));p.Blocks.Add(condition);await runtime.Start(p);Assert(runtime.Errors.Count==0&&RuntimeView.Number(runtime.Get("expr"))==13&&RuntimeView.Number(runtime.Get("wynik"))==12&&(string)runtime.Get("element")=="B"&&RuntimeView.Number(runtime.Get("ile"))==3&&(string)runtime.Get("branch")=="tak","Zmienne/listy/wyrażenia");Assert(RuntimeView.Truth(runtime.Value("=1 + 2 * 3 == 7 && !(2 > 3)")),"Priorytety wyrażeń");results.Add("PASS zmienne, obliczenia, parser, listy, warunki z alternatywą");
  p=new Project();p.Blocks.Add(B("set","suma","0"));Block loop=B("for","i","1","4","1");loop.Children.Add(B("change","suma","{i}"));p.Blocks.Add(loop);Block disabled=B("set","suma","100");disabled.Disabled=true;p.Blocks.Add(disabled);await runtime.Start(p);Assert(RuntimeView.Number(runtime.Get("suma"))==10,"Pętla i wyłączony bloczek");p.Features["Zmienne"]=false;await runtime.Start(p);Assert(!runtime.Values.ContainsKey("suma"),"Wyłączona kategoria");results.Add("PASS pętle, wyłączenie bloczka i całej grupy funkcji");
  p=Examples.Movement();await runtime.Start(p);runtime.FeedKey(Keys.Right,true);await Task.Delay(40);Assert(runtime.Stage.Sprites["robot"].X==15,"Ruch i klawiatura");runtime.FeedKey(Keys.Right,false);results.Add("PASS duszki, dymki, zdarzenia klawiatury i ruch");
  p=new Project();p.Blocks.AddRange(new[]{B("sprite_add","robot","kot","#ffaa00"),B("pen_down"),B("move","20"),B("turn","90"),B("move","10"),B("stamp")});await runtime.Start(p);Assert(runtime.Stage.Lines.Count==2&&runtime.Stage.Stamps.Count==1&&Math.Abs(runtime.Stage.Sprites["robot"].Y-10)<.01,"Pisak");results.Add("PASS pisak, obrót, ślad ruchu i stemplowanie");
  p=new Project();p.Blocks.Add(B("set","n","0"));Block forever=B("forever");forever.Children.Add(B("change","n","1"));p.Blocks.Add(forever);Task job=runtime.Start(p);await Task.Delay(80);runtime.Stop();await job;Assert(RuntimeView.Number(runtime.Get("n"))>0,"Zatrzymanie pętli");results.Add("PASS pętla zawsze pozostawia GUI responsywne i daje się zatrzymać");
  await runtime.Design(Examples.Gui());Assert(runtime.Stage.Design&&runtime.Stage.Elements.Count==9&&runtime.Errors.Count==0,"Projektant");results.Add("PASS projektant GUI odtwarza elementy bez uruchamiania zdarzeń");
  p=new Project();p.Blocks.Add(B("set","msg","0"));Block recv=B("event_message","test");recv.Children.Add(B("change","msg","1"));p.Blocks.Add(recv);p.Blocks.Add(B("broadcast","test"));await runtime.Start(p);await Task.Delay(20);Assert(RuntimeView.Number(runtime.Get("msg"))==1,"Wiadomości");results.Add("PASS nadawanie wiadomości i obsługa odbiorcy");
  p=Examples.Game();Task game=runtime.Start(p);await Task.Delay(70);Sprite target=runtime.Stage.Sprites["cel"],player=runtime.Stage.Sprites["gracz"];player.X=target.X;player.Y=target.Y;await Task.Delay(100);Assert(RuntimeView.Number(runtime.Get("punkty"))>=1,"Zbieranie gwiazdy");runtime.Stop();await game;results.Add("PASS gra: równoległe zdarzenia, pomiar odległości i zbieranie punktów");
  await runtime.Start(Examples.Drawing());Assert(runtime.Errors.Count==0&&runtime.Stage.Lines.Count==288,"Przykład rysowania");results.Add("PASS animowany rysunek z pętlą zagnieżdżoną");
  p=new Project();p.Features["Pliki"]=true;string fixture=Path.Combine(directory,"odczyt.txt");File.WriteAllText(fixture,"Zażółć gęślą jaźń",Encoding.UTF8);p.Blocks.Add(B("file_read",fixture,"tekst"));p.Blocks.Add(B("file_exists",fixture,"jest"));await runtime.Start(p);Assert((string)runtime.Get("tekst")=="Zażółć gęślą jaźń"&&RuntimeView.Number(runtime.Get("jest"))==1,"Pliki UTF8");p.Features["Pliki"]=false;await runtime.Start(p);Assert(!runtime.Values.ContainsKey("tekst"),"Wyłączenie plików");results.Add("PASS odczyt plików UTF-8 i rzeczywiste wyłączenie obsługi plików");
  p=new Project();p.Blocks.Add(B("set","bad","=5 / 0"));await runtime.Start(p);Assert(runtime.Errors.Count==1,"Dzielenie przez zero");bool rejected=false;try{runtime.Value("="+new string('!',200)+"1");}catch{rejected=true;}Assert(rejected,"Limit złożoności wyrażeń");results.Add("PASS błędy obliczeń i limit złożoności wyrażeń");
  string testJs=Path.Combine(directory,"program ze spacją ż.js");File.WriteAllText(testJs,ProjectIO.Export(Examples.Counter(),Application.ExecutablePath),Encoding.ASCII);using(Process loader=Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"cscript.exe"),"//E:JScript //nologo \""+testJs+"\" /easyjava-test"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){bool ended=await Task.Run(()=>loader.WaitForExit(20000));if(!ended){loader.Kill();throw new Exception("Loader nie zakończył testu.");}string err=loader.StandardError.ReadToEnd()+loader.StandardOutput.ReadToEnd();Assert(loader.ExitCode==0,"WSH loader: "+err);}results.Add("PASS realny Windows Script Host uruchamia samodzielny plik .js z GUI bez Node.js");
  foreach(int i in new[]{1,2,3,6,7,8}){await runtime.Start(Examples.Create(i));Assert(runtime.Errors.Count==0,"Przykład "+i+": "+string.Join(";",runtime.Errors));}results.Add("PASS przykłady GUI, licznik, sterowanie, lista i notatnik");
 }catch(Exception ex){exit=1;results.Add("FAIL "+ex.ToString());}File.WriteAllText(Path.Combine(directory,"results.txt"),string.Join(Environment.NewLine,results),Encoding.UTF8);runtime.Stop();form.Close();};Application.Run(form);}return exit;}
}
}
